/**
 * The tab icon follows the app's own theme button, not just the browser's colour scheme.
 * Pearl uses the owner's lt04 transparent mark (black edges), Vault uses lt02 (white edges):
 * public/favicon-light.svg and public/favicon-dark.svg, both generated by docs/brand/build-logo-kit.py.
 * index.html keeps the scheme-adaptive /favicon.svg as the first-paint and no-JavaScript default.
 */
export type ResolvedTheme = "paper" | "vault";

export function faviconHref(theme: ResolvedTheme): string {
  return theme === "vault" ? "/favicon-dark.svg" : "/favicon-light.svg";
}

/** Points the page's SVG icon link at the file that matches `theme`. Safe to call repeatedly. */
export function applyFavicon(theme: ResolvedTheme, doc: Document = document): void {
  const link = doc.querySelector<HTMLLinkElement>('link[rel="icon"][type="image/svg+xml"]');
  const href = faviconHref(theme);
  if (link && link.getAttribute("href") !== href) link.setAttribute("href", href);
}
